{"rob": "robolang 1.3;

task relay(robot arm, robot amr, object box, location src, location hand, location dst, region zone) {
    goal { object_at box dst; }
    plan {
        move arm to src;
        grasp arm box;
        move arm to hand;
        place arm box at hand;
        wait until region_clear zone timeout 30 s;
        move amr to hand;
        grasp amr box;
        move amr to dst;
        place amr box at dst;
    }
}
", "task": "relay", "bindings": [{"param": "arm", "id": "arm1"}, {"param": "amr", "id": "amr1"}, {"param": "box", "id": "box1"}, {"param": "src", "id": "shelf"}, {"param": "hand", "id": "handoff"}, {"param": "dst", "id": "table"}, {"param": "zone", "id": "handoff_zone"}]}
